  Theorem gc_run : forall regs,
    getr regs 10 = Z_to_bv 64 fs -> getr regs 11 = Z_to_bv 64 sparg -> getr regs 4 = Z_to_bv 64 tpv -> getr regs 2 = sp -> getr regs 1 = ra ->
    exists regs' Mj,
      msteps ASEGS (mkst regs (0x662f4 : word) mem0 rom) (mkst regs' ra (wbytes Mj (Z_to_bv 64 (fs + 96)) [Z_to_bv 8 0]) rom)   (* [comment removed for export] *)
